[asy]
unitsize(2.5 cm);

pair A, B, C, D, P;
pair[] M;

A = dir(118);
B = dir(62);
C = dir(323);
D = dir(165);
M[12] = (A + B)/2;
M[13] = (A + C)/2;
M[14] = (A + D)/2;
M[23] = (B + C)/2;
M[24] = (B + D)/2;
M[34] = (C + D)/2;
P = (A + B + C + D)/2;

draw(Circle((0,0),1),red);
draw(A--B,green);
draw(A--C,green);
draw(A--D,green);
draw(B--C,green);
draw(B--D,green);
draw(C--D,green);
draw(interp(M[12],P,-2)--interp(M[12],P,6),dashed);
draw(interp(M[13],P,-2)--interp(M[13],P,2),dashed);
draw(interp(M[14],P,-0.5)--interp(M[14],P,2.5),dashed);
draw(interp(M[23],P,-0.7)--interp(M[23],P,1.5),dashed);
draw(interp(M[24],P,-3.3)--interp(M[24],P,4),dashed);
draw(interp(M[34],P,-0.3)--interp(M[34],P,1.6),dashed);

dot("$A$", A, A);
dot("$B$", B, B);
dot("$C$", C, C);
dot("$D$", D, D);
dot(M[12]);
dot(M[13]);
dot(M[14]);
dot(M[23]);
dot(M[24]);
dot(M[34]);
[/asy]

